const esc = (s) => String(s).replace(/&/g, "&amp;").replace(/"/g, "&quot;").replace(/</g, "&lt;");
export async function onRequestGet({ request, env }) {
  const res = await env.ASSETS.fetch(request);
  try {
    const u = new URL(request.url), m = OG[u.searchParams.get("c") || ""];
    if (!m || !(res.headers.get("content-type") || "").includes("text/html")) return res;
    const img = m.s ? `${u.origin}/covers/${m.s}.jpg` : "";
    const tags = `<meta property="og:type" content="website"><meta property="og:site_name" content="สรุปให้ตัวไหนดี">` +
      `<meta property="og:title" content="${esc(m.t)}"><meta property="og:description" content="${esc(m.d)}">` +
      `<meta property="og:url" content="${esc(u.href)}">` + (img ? `<meta property="og:image" content="${img}">` : "");
    return new HTMLRewriter()
      .on("title", { element(e) { e.setInnerContent(m.t); } })
      .on('meta[name="description"]', { element(e) { e.setAttribute("content", m.d); } })
      .on("head", { element(e) { e.append(tags, { html: true }); } })
      .transform(res);
  } catch (e) { return res; }
}
